/**
 * Sample the world's land onto a dot grid, once, and commit the result.
 *
 * WHY A GENERATED FILE AND NOT A RUNTIME LIBRARY. The footprint map needs
 * about two thousand points and nothing else from a geo stack. Shipping
 * d3-geo, topojson-client and a 100KB atlas to the browser (and to a Worker
 * with a bundle budget) to arrive at a list of coordinates that never changes
 * would be the wrong trade — so the libraries are devDependencies, this
 * script runs them, and `src/lib/footprints/world-dots.ts` is what ships.
 * The diff of that file is reviewable; if it changes and nothing here did,
 * something is wrong.
 *
 * THE PROJECTION IS NOT DEFINED HERE. It is imported from
 * `src/lib/footprints/projection.ts`, the same module `footprints.ts` pins
 * stops with, so a dot and a stop can only disagree if that file is edited
 * and this one is not re-run. The constants used are stamped into the output
 * (`WORLD_DOTS_PROJECTION`) and U-FOOT-T5 compares the stamp to the live
 * constants.
 *
 * DETERMINISTIC ON PURPOSE. Same atlas version, same grid, same output byte
 * for byte: no timestamps, no ordering that depends on the machine. Run it
 * twice and `git diff` must be empty.
 *
 *   pnpm generate:world-dots
 */
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";

import { geoContains } from "d3-geo";
import { feature } from "topojson-client";

import {
  GRID_STEP,
  LAT_MAX,
  LAT_MIN,
  LNG_MAX,
  LNG_MIN,
  SCALE,
  VIEWBOX,
  project,
} from "../src/lib/footprints/projection";

const OUT = path.resolve(import.meta.dirname, "..", "src", "lib", "footprints", "world-dots.ts");

const require = createRequire(import.meta.url);
const atlasFile = require.resolve("world-atlas/land-110m.json");
const atlasVersion = (
  JSON.parse(readFileSync(path.join(path.dirname(atlasFile), "package.json"), "utf8")) as {
    version: string;
  }
).version;

// The topology types come from `feature`'s own signature: their package
// (@types/topojson-specification) is only a transitive dependency, and pnpm
// does not let a script import what it did not declare.
type Topology = Parameters<typeof feature>[0];
const topology = JSON.parse(readFileSync(atlasFile, "utf8")) as Topology & {
  objects: { land: Parameters<typeof feature>[1] };
};
const land = feature(topology, topology.objects.land);

/** Cell centres, so a coastline is rounded the same way on every side. */
const cols = Math.floor((LNG_MAX - LNG_MIN) / GRID_STEP);
const rows = Math.floor((LAT_MAX - LAT_MIN) / GRID_STEP);

const lines: string[] = [];
const segments: string[] = [];
let count = 0;

for (let row = 0; row < rows; row++) {
  const lat = LAT_MAX - (row + 0.5) * GRID_STEP;
  const cells: string[] = [];
  for (let col = 0; col < cols; col++) {
    const lng = LNG_MIN + (col + 0.5) * GRID_STEP;
    if (!geoContains(land, [lng, lat])) continue;
    const { x, y } = project([lng, lat]);
    cells.push(`[${x},${y}]`);
    segments.push(`M${x} ${y}h0`);
    count++;
  }
  if (cells.length) lines.push(`  ${cells.join(",")},`);
}

const source = `/**
 * GENERATED by scripts/generate-world-dots.ts — do not edit by hand.
 *
 * Regenerate with \`pnpm generate:world-dots\`. Source: world-atlas@${atlasVersion}
 * land-110m, sampled at cell centres on a ${GRID_STEP} degree grid, latitude
 * ${LAT_MAX} to ${LAT_MIN}. ${count} dots.
 *
 * Positions are already in the map's SVG units (see projection.ts), so the
 * browser draws them without projecting anything and imports no geo library.
 * \`WORLD_DOTS_PATH\` is the same points as one path — a \`M x y h0\` per dot,
 * drawn with a round line cap — because two thousand <circle> elements are two
 * thousand DOM nodes and this is one.
 */

/** The projection constants this file was generated with; U-FOOT-T5 compares them to projection.ts. */
export const WORLD_DOTS_PROJECTION = {
  gridStep: ${GRID_STEP},
  lngMin: ${LNG_MIN},
  lngMax: ${LNG_MAX},
  latMax: ${LAT_MAX},
  latMin: ${LAT_MIN},
  scale: ${SCALE},
  width: ${VIEWBOX.width},
  height: ${VIEWBOX.height},
} as const;

/** [x, y] in SVG units, top row first. */
export const WORLD_DOTS: readonly (readonly [number, number])[] = [
${lines.join("\n")}
];

export const WORLD_DOTS_PATH = ${JSON.stringify(segments.join(""))};
`;

writeFileSync(OUT, source);
console.log(`world-dots: ${count} dots, ${source.length} bytes -> ${path.relative(process.cwd(), OUT)}`);
process.exit(0);
